css:
.print-format {
font-family: Arial, sans-serif;
font-size: 12px;
color: #000;
padding: 20px;
}
.header {
text-align: center;
margin-bottom: 20px;
}
.header h1 {
margin: 0;
font-size: 24px;
}
.header p {
margin: 4px 0;
}
.section {
margin-bottom: 20px;
}
.section-title {
font-size: 16px;
font-weight: bold;
border-bottom: 1px solid #000;
margin-bottom: 10px;
padding-bottom: 4px;
}
table {
width: 100%;
border-collapse: collapse;
}
td {
padding: 8px;
vertical-align: top;
}
.label {
    font-weight: bold;
    width: 35%;
}

.value {
    font-weight: normal;
}
